1: (() => {
2:   'use strict';
3:   const canvas = document.getElementById('game');
4:   const ctx = canvas.getContext('2d');
5:   const $ = (id) => document.getElementById(id);
6:   const ui = { start: $('start-screen'), end: $('end-screen'), hud: $('hud'), pause: $('pause-badge'), collect: $('collect-count'), health: $('health-value'), healthMeter: $('health-meter'), ammo: $('ammo-value'), reserve: $('ammo-reserve'), weapon: $('weapon-name'), slot: $('slot-name'), toast: $('toast'), endTitle: $('end-title'), endKicker: $('end-kicker'), endCopy: $('end-copy'), report: $('run-report') };
7:   const MAP = [
8:     '#################', '#...............#', '#..##.....##....#', '#..##.....##....#', '#...............#', '#.....#.........#', '###...#...####..#', '#.....#.........#', '#...............#', '#....##.....##..#', '#....##.....##..#', '#...............#', '#################'
9:   ];
10:   const WEAPONS = [
11:     { id:'sidekick', name:'SIDEKICK', label:'SIDEKICK // 9MM', color:'#d5ff64', damage:34, rate:330, clip:12, reserve:48, spread:.018, pellets:1, auto:false },
12:     { id:'buzzcut', name:'BUZZCUT SMG', label:'BUZZCUT // .45 AUTO', color:'#ffb45c', damage:17, rate:105, clip:32, reserve:128, spread:.045, pellets:1, auto:true },
13:     { id:'breacher', name:'BREACHER', label:'BREACHER // 12 GA', color:'#ff714f', damage:14, rate:650, clip:8, reserve:32, spread:.13, pellets:7, auto:false },
14:     { id:'longshot', name:'LONGSHOT', label:'LONGSHOT // 5.56', color:'#67d8ff', damage:68, rate:580, clip:10, reserve:50, spread:.006, pellets:1, auto:false },
15:     { id:'arc', name:'ARC CASTER', label:'ARC CASTER // ION', color:'#c88aff', damage:48, rate:440, clip:18, reserve:72, spread:.025, pellets:1, auto:true }
16:   ];
17:   const keys = Object.create(null);
18:   let W = 960, H = 540, running = false, paused = false, gameOver = false, last = 0, lastShot = 0, reloadUntil = 0, toastTimer = 0, damageFlash = 0, muzzle = 0, kills = 0, gunsCollected = 0, fireHeld = false, audio = null;
19:   let player, guns, enemies, exit, zBuffer = new Float32Array(W), view = { x:0, y:0, dirX:1, dirY:0, planeX:0, planeY:.66 };
20:   function resize(){const cw=innerWidth,ch=innerHeight; W=Math.max(480,Math.min(1100,Math.floor(cw*.88))); H=Math.max(270,Math.round(W*ch/cw)); canvas.width=W;canvas.height=H;zBuffer=new Float32Array(W);}
21:   addEventListener('resize',resize); resize();
22:   function createState(){
23:     player={x:1.55,y:1.55,angle:0,health:100,weapon:0,ammo:12,reserve:48,inventory:[0],bob:0,moving:false};
24:     guns=[{x:5.35,y:1.55,type:1,taken:false},{x:13.5,y:4.5,type:2,taken:false},{x:2.5,y:8.5,type:3,taken:false},{x:12.5,y:10.5,type:4,taken:false}];
25:     enemies=[{x:10.5,y:1.6,hp:70,max:70,attack:0,seed:1},{x:14.5,y:7.7,hp:95,max:95,attack:.8,seed:2},{x:5.5,y:10.5,hp:75,max:75,attack:1.7,seed:3},{x:8.5,y:4.5,hp:75,max:75,attack:2.4,seed:4}];
26:     exit={x:15.15,y:11.2}; gunsCollected=0;kills=0;lastShot=0;reloadUntil=0;muzzle=0;damageFlash=0;gameOver=false;paused=false;
27:   }
28:   createState();
29:   // Every map character except a dot is solid.
30:   function solid(x,y){const mx=Math.floor(x),my=Math.floor(y);return !MAP[my]||MAP[my][mx]!=='.';}
31:   function canStand(x,y,r=.2){return !solid(x-r,y-r)&&!solid(x+r,y-r)&&!solid(x-r,y+r)&&!solid(x+r,y+r);}
32:   function showToast(message){ui.toast.textContent=message;ui.toast.classList.add('show');toastTimer=1.65;}
33:   function updateHud(){const w=WEAPONS[player.weapon];ui.collect.textContent=`${gunsCollected} / 3`;ui.health.textContent=Math.max(0,Math.ceil(player.health));ui.healthMeter.style.width=`${Math.max(0,player.health)}%`;ui.healthMeter.style.background=player.health<35?'#ff604e':'#d5ff64';ui.ammo.textContent=player.ammo;ui.reserve.textContent=` / ${player.reserve}`;ui.weapon.textContent=w.label;ui.slot.textContent=w.name;}
34:   function begin(){createState();running=true;paused=false;ui.start.classList.add('hidden');ui.end.classList.add('hidden');ui.hud.hidden=false;ui.pause.hidden=true;updateHud();try{canvas.requestPointerLock?.();}catch(_){}last=performance.now();}
35:   $('start-button').addEventListener('click',begin);$('restart-button').addEventListener('click',begin);
36:   document.addEventListener('pointerlockchange',()=>{if(!running||gameOver)return;if(document.pointerLockElement!==canvas&&!matchMedia('(max-width:700px)').matches){paused=true;fireHeld=false;ui.pause.hidden=false;}else if(document.pointerLockElement===canvas){paused=false;ui.pause.hidden=true;last=performance.now();}});
37:   canvas.addEventListener('click',()=>{if(running&&!gameOver&&paused){canvas.requestPointerLock?.();return;}if(running&&!paused&&document.pointerLockElement!==canvas&&!matchMedia('(max-width:700px)').matches){canvas.requestPointerLock?.();}});
38:   document.addEventListener('mousemove',e=>{if(running&&!paused&&!gameOver&&document.pointerLockElement===canvas)player.angle+=e.movementX*.00235;});
39:   document.addEventListener('keydown',e=>{const k=e.key.toLowerCase();keys[k]=true;if([' ','arrowup','arrowdown','arrowleft','arrowright'].includes(k))e.preventDefault();if(!running||paused||gameOver)return;if(k==='r')reload();if(k==='e')interact();if(k>='1'&&k<='5')switchWeapon(+k-1);});
40:   document.addEventListener('keyup',e=>{keys[e.key.toLowerCase()]=false;});
41:   document.addEventListener('mousedown',e=>{if(e.button===0&&running&&!paused&&!gameOver){fireHeld=true;shoot();}});document.addEventListener('mouseup',e=>{if(e.button===0)fireHeld=false;});
42:   addEventListener('blur',()=>{fireHeld=false;Object.keys(keys).forEach(k=>keys[k]=false);});
43:   function reload(){if(reloadUntil||player.ammo===WEAPONS[player.weapon].clip||player.reserve<=0)return;reloadUntil=performance.now()+850;showToast('RELOADING');}
